@pytest.mark.parametrize('query, num_results, expected_output, http_code, error_msg', [('invalid query', 3, 'Error: <HttpError 400 when requesting https://www.googleapis.com/customsearch/v1?q=invalid+query&cx returned "Invalid Value". Details: "Invalid Value">', 400, 'Invalid Value'), ('invalid API key', 3, 'Error: The provided Google API key is invalid or missing.', 403, 'invalid API key')])
def test_google_official_search_errors(query, num_results, expected_output, mock_googleapiclient, http_code, error_msg, agent: Agent):

