def deep_merge(source: Dict[Any, Any], dest: Dict[Any, Any]) -> Dict[Any, Any]:
    for (key, value) in source.items():
        if isinstance(value, Dict):
            dest[key] = deep_merge(value, dest.get(key, {}))
        else:
            dest[key] = value
    return dest

def recursive_sort_dict(data: dict) -> dict:
