def meter_api(func: Callable):
    """Adds ApiManager metering to functions which make OpenAI API calls"""
    from autogpt.llm.api_manager import ApiManager
    api_manager = ApiManager()
    openai_obj_processor = openai.util.convert_to_openai_object

    def update_usage_with_response(response: OpenAIObject):
        try:
            usage = response.usage
            logger.debug(f'Reported usage from call to model {response.model}: {usage}')
            api_manager.update_cost(response.usage.prompt_tokens, response.usage.completion_tokens if 'completion_tokens' in usage else 0, response.model)
        except Exception as err:
            logger.warn(f'Failed to update API costs: {err.__class__.__name__}: {err}')

    def metering_wrapper(*args, **kwargs):
        openai_obj = openai_obj_processor(*args, **kwargs)
        if isinstance(openai_obj, OpenAIObject) and 'usage' in openai_obj:
            update_usage_with_response(openai_obj)
        return openai_obj

    def metered_func(*args, **kwargs):
        with patch.object(engine_api_resource.util, 'convert_to_openai_object', side_effect=metering_wrapper):
            return func(*args, **kwargs)
    return metered_func

def retry_api(max_retries: int=10, backoff_base: float=2.0, warn_user: bool=True):
    """Retry an OpenAI API call.

    Args:
        num_retries int: Number of retries. Defaults to 10.
        backoff_base float: Base for exponential backoff. Defaults to 2.
        warn_user bool: Whether to warn the user. Defaults to True.
    """
    error_messages = {ServiceUnavailableError: f'{Fore.RED}Error: The OpenAI API engine is currently overloaded{Fore.RESET}', RateLimitError: f'{Fore.RED}Error: Reached rate limit{Fore.RESET}'}
    api_key_error_msg = f'Please double check that you have setup a {Fore.CYAN + Style.BRIGHT}PAID{Style.RESET_ALL} OpenAI API Account. You can read more here: {Fore.CYAN}https://docs.agpt.co/setup/#getting-an-api-key{Fore.RESET}'
    backoff_msg = f'{Fore.RED}Waiting {{backoff}} seconds...{Fore.RESET}'

    def _wrapper(func: Callable):

        @functools.wraps(func)
        def _wrapped(*args, **kwargs):
            user_warned = not warn_user
            max_attempts = max_retries + 1
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except (RateLimitError, ServiceUnavailableError) as e:
                    if attempt >= max_attempts or (isinstance(e, RateLimitError) and (err := getattr(e, 'error', {})) and (err.get('code') == 'insufficient_quota')):
                        raise
                    error_msg = error_messages[type(e)]
                    logger.warn(error_msg)
                    if not user_warned:
                        logger.double_check(api_key_error_msg)
                        logger.debug(f'Status: {e.http_status}')
                        logger.debug(f'Response body: {e.json_body}')
                        logger.debug(f'Response headers: {e.headers}')
                        user_warned = True
                except (APIError, Timeout) as e:
                    if e.http_status not in [429, 502] or attempt == max_attempts:
                        raise
                backoff = backoff_base ** (attempt + 2)
                logger.warn(backoff_msg.format(backoff=backoff))
                time.sleep(backoff)
        return _wrapped
    return _wrapper

