class OpenAIFunctionSpec:
    """Represents a "function" in OpenAI, which is mapped to a Command in Auto-GPT"""
    name: str
    description: str
    parameters: dict[str, ParameterSpec]

    @dataclass
    class ParameterSpec:
        name: str
        type: str
        description: Optional[str]
        required: bool = False

    @property
    def schema(self) -> dict[str, str | dict | list]:
        """Returns an OpenAI-consumable function specification"""
        return {'name': self.name, 'description': self.description, 'parameters': {'type': 'object', 'properties': {param.name: {'type': param.type, 'description': param.description} for param in self.parameters.values()}, 'required': [param.name for param in self.parameters.values() if param.required]}}

    @property
    def prompt_format(self) -> str:
        """Returns the function formatted similarly to the way OpenAI does it internally:
        https://community.openai.com/t/how-to-calculate-the-tokens-when-using-function-call/266573/18

        Example:
        ```ts
        // Get the current weather in a given location
        type get_current_weather = (_: {
        // The city and state, e.g. San Francisco, CA
        location: string,
        unit?: "celsius" | "fahrenheit",
        }) => any;
        ```
        """

        def param_signature(p_spec: OpenAIFunctionSpec.ParameterSpec) -> str:
            return (f'// {p_spec.description}\n' if p_spec.description else '') + f"{p_spec.name}{('' if p_spec.required else '?')}: {p_spec.type},"
        return '\n'.join([f'// {self.description}', f'type {self.name} = (_ :{{', *[param_signature(p) for p in self.parameters.values()], '}) => any;'])

def get_openai_command_specs(command_registry: CommandRegistry) -> list[OpenAIFunctionSpec]:
    """Get OpenAI-consumable function specs for the agent's available commands.
    see https://platform.openai.com/docs/guides/gpt/function-calling
    """
    return [OpenAIFunctionSpec(name=command.name, description=command.description, parameters={param.name: OpenAIFunctionSpec.ParameterSpec(name=param.name, type=param.type, required=param.required, description=param.description) for param in command.parameters}) for command in command_registry.commands.values()]

