    type get_current_weather = (_: {
    // The city and state, e.g. San Francisco, CA
    location: string,
    unit?: "celsius" | "fahrenheit",
    }) => any;

    } // namespace functions
    ```
    """
    return 'namespace functions {\n\n' + '\n\n'.join((f.prompt_format for f in functions)) + '\n\n} // namespace functions'

