def create_chat_completion(prompt: ChatSequence, config: Config, functions: Optional[List[OpenAIFunctionSpec]]=None, model: Optional[str]=None, temperature: Optional[float]=None, max_tokens: Optional[int]=None) -> ChatModelResponse:
    """Create a chat completion using the OpenAI API

    Args:
        messages (List[Message]): The messages to send to the chat completion
        model (str, optional): The model to use. Defaults to None.
        temperature (float, optional): The temperature to use. Defaults to 0.9.
        max_tokens (int, optional): The max tokens to use. Defaults to None.

    Returns:
        str: The response from the chat completion
    """
    if model is None:
        model = prompt.model.name
    if temperature is None:
        temperature = config.temperature
    if max_tokens is None:
        prompt_tlength = prompt.token_length
        max_tokens = OPEN_AI_CHAT_MODELS[model].max_tokens - prompt_tlength - 1
        logger.debug(f'Prompt length: {prompt_tlength} tokens')
        if functions:
            functions_tlength = count_openai_functions_tokens(functions, model)
            max_tokens -= functions_tlength
            logger.debug(f'Functions take up {functions_tlength} tokens in API call')
    logger.debug(f'{Fore.GREEN}Creating chat completion with model {model}, temperature {temperature}, max_tokens {max_tokens}{Fore.RESET}')
    chat_completion_kwargs = {'model': model, 'temperature': temperature, 'max_tokens': max_tokens}
    for plugin in config.plugins:
        if plugin.can_handle_chat_completion(messages=prompt.raw(), **chat_completion_kwargs):
            message = plugin.handle_chat_completion(messages=prompt.raw(), **chat_completion_kwargs)
            if message is not None:
                return message
    chat_completion_kwargs.update(config.get_openai_credentials(model))
    if functions:
        chat_completion_kwargs['functions'] = [function.schema for function in functions]
    logger.debug(prompt.dump())
    response = iopenai.create_chat_completion(messages=prompt.raw(), **chat_completion_kwargs)
    logger.debug(f'Response: {response}')
    if hasattr(response, 'error'):
        logger.error(response.error)
        raise RuntimeError(response.error)
    first_message: ResponseMessageDict = response.choices[0].message
    content: str | None = first_message.get('content')
    function_call: FunctionCallDict | None = first_message.get('function_call')
    for plugin in config.plugins:
        if not plugin.can_handle_on_response():
            continue
        content = plugin.on_response(content)
    return ChatModelResponse(model_info=OPEN_AI_CHAT_MODELS[model], content=content, function_call=OpenAIFunctionCall(name=function_call['name'], arguments=function_call['arguments']) if function_call else None)

