def update_user(config: Config, ai_config: AIConfig, command_name: CommandName | None, command_args: CommandArgs | None, assistant_reply_dict: AgentThoughts) -> None:
    """Prints the assistant's thoughts and the next command to the user.

    Args:
        config: The program's configuration.
        ai_config: The AI's configuration.
        command_name: The name of the command to execute.
        command_args: The arguments for the command.
        assistant_reply_dict: The assistant's reply.
    """
    print_assistant_thoughts(ai_config.ai_name, assistant_reply_dict, config)
    if command_name is not None:
        if command_name.lower().startswith('error'):
            logger.typewriter_log('ERROR: ', Fore.RED, f'The Agent failed to select an action. Error message: {command_name}')
        else:
            if config.speak_mode:
                say_text(f'I want to execute {command_name}', config)
            logger.typewriter_log('\n')
            logger.typewriter_log('NEXT ACTION: ', Fore.CYAN, f'COMMAND = {Fore.CYAN}{remove_ansi_escape(command_name)}{Style.RESET_ALL}  ARGUMENTS = {Fore.CYAN}{command_args}{Style.RESET_ALL}')
    else:
        logger.typewriter_log('NO ACTION SELECTED: ', Fore.RED, f'The Agent failed to select an action.')

/autogpt.app.main/get_user_feedback.code:
def get_user_feedback(config: Config, ai_config: AIConfig) -> tuple[UserFeedback, str, int | None]:
    """Gets the user's feedback on the assistant's reply.

    Args:
        config: The program's configuration.
        ai_config: The AI's configuration.

    Returns:
        A tuple of the user's feedback, the user's input, and the number of
        cycles remaining if the user has initiated a continuous cycle.
    """
    logger.info(f"Enter '{config.authorise_key}' to authorise command, '{config.authorise_key} -N' to run N continuous commands, '{config.exit_key}' to exit program, or enter feedback for {ai_config.ai_name}...")
    user_feedback = None
    user_input = ''
    new_cycles_remaining = None
    while user_feedback is None:
        if config.chat_messages_enabled:
            console_input = clean_input(config, 'Waiting for your response...')
        else:
            console_input = clean_input(config, Fore.MAGENTA + 'Input:' + Style.RESET_ALL)
        if console_input.lower().strip() == config.authorise_key:
            user_feedback = UserFeedback.AUTHORIZE
        elif console_input.lower().strip() == '':
            logger.warn('Invalid input format.')
        elif console_input.lower().startswith(f'{config.authorise_key} -'):
            try:
                user_feedback = UserFeedback.AUTHORIZE
                new_cycles_remaining = abs(int(console_input.split(' ')[1]))
            except ValueError:
                logger.warn(f"Invalid input format. Please enter '{config.authorise_key} -N' where N is the number of continuous tasks.")
        elif console_input.lower() in [config.exit_key, 'exit']:
            user_feedback = UserFeedback.EXIT
        else:
            user_feedback = UserFeedback.TEXT
            user_input = console_input
    return (user_feedback, user_input, new_cycles_remaining)

