def get_azure_credentials(self, model: str) -> dict[str, str]:
    """Get the kwargs for the Azure API."""
    fast_llm = self.fast_llm if not (self.fast_llm == self.smart_llm and self.fast_llm.startswith(GPT_4_MODEL)) else f'not_{self.fast_llm}'
    smart_llm = self.smart_llm if not (self.smart_llm == self.fast_llm and self.smart_llm.startswith(GPT_3_MODEL)) else f'not_{self.smart_llm}'
    deployment_id = {fast_llm: self.azure_model_to_deployment_id_map.get('fast_llm_deployment_id', self.azure_model_to_deployment_id_map.get('fast_llm_model_deployment_id')), smart_llm: self.azure_model_to_deployment_id_map.get('smart_llm_deployment_id', self.azure_model_to_deployment_id_map.get('smart_llm_model_deployment_id')), self.embedding_model: self.azure_model_to_deployment_id_map.get('embedding_model_deployment_id')}.get(model, None)
    kwargs = {'api_type': self.openai_api_type, 'api_base': self.openai_api_base, 'api_version': self.openai_api_version}
    if model == self.embedding_model:
        kwargs['engine'] = deployment_id
    else:
        kwargs['deployment_id'] = deployment_id
    return kwargs

