    if thought_process_id != 'one-shot':
        raise NotImplementedError(f"Unknown thought process '{thought_process_id}'")
    RESPONSE_FORMAT_WITH_COMMAND = '```ts
        interface Response {
            thoughts: {
                // Thoughts
                text: string;
                reasoning: string;
                // Short markdown-style bullet list that conveys the long-term plan
                plan: string;
                // Constructive self-criticism
                criticism: string;
                // Summary of thoughts to say to the user
                speak: string;
            };
            command: {
                name: string;
                args: Record<string, any>;
            };
        }
        ```'
    RESPONSE_FORMAT_WITHOUT_COMMAND = '```ts
        interface Response {
            thoughts: {
                // Thoughts
                text: string;
                reasoning: string;
                // Short markdown-style bullet list that conveys the long-term plan
                plan: string;
                // Constructive self-criticism
                criticism: string;
                // Summary of thoughts to say to the user
                speak: string;
            };
        }
        ```'
    response_format = re.sub('\n\s+', '
', RESPONSE_FORMAT_WITHOUT_COMMAND if self.config.openai_functions else RESPONSE_FORMAT_WITH_COMMAND)
    use_functions = self.config.openai_functions and self.command_registry.commands
    return f"Respond strictly with JSON{(', and also specify a command to use through a function_call' if use_functions else '')}. The JSON should be compatible with the TypeScript type `Response` from the following:
{response_format}
"

