class Command:
    label: str
    name: str
    params: dict[str, str]
    function: Optional[Callable]

    def __str__(self) -> str:
        """Returns a string representation of the command."""
        params_string = ', '.join((f'"{key}": "{value}"' for (key, value) in self.params.items()))
        return f'{self.label}: "{self.name}", params: ({params_string})'

def _generate_commands(self) -> str:
    command_strings = []
    if self.command_registry:
        command_strings += [str(cmd) for cmd in self.command_registry.commands.values() if cmd.enabled]
    command_strings += [str(cmd) for cmd in self.commands]
    return self._generate_numbered_list(command_strings)

