@command('list_files', 'Lists Files in a Directory', {'directory': {'type': 'string', 'description': 'The directory to list files in', 'required': True}})
@sanitize_path_arg('directory')
def list_files(directory: str, agent: Agent) -> list[str]:
    """lists files in a directory recursively

    Args:
        directory (str): The directory to search in

    Returns:
        list[str]: A list of files found in the directory
    """
    found_files = []
    for (root, _, files) in os.walk(directory):
        for file in files:
            if file.startswith('.'):
                continue
            relative_path = os.path.relpath(os.path.join(root, file), agent.config.workspace_path)
            found_files.append(relative_path)
    return found_files

