@command('execute_python_file', 'Executes an existing Python file', {'filename': {'type': 'string', 'description': 'The name of te file to execute', 'required': True}})
@sanitize_path_arg('filename')
def execute_python_file(filename: str, agent: Agent) -> str:
    """Execute a Python file in a Docker container and return the output

    Args:
        filename (str): The name of the file to execute

    Returns:
        str: The output of the file
    """
    logger.info(f"Executing python file '{filename}' in working directory '{agent.config.workspace_path}'")
    if not filename.endswith('.py'):
        return 'Error: Invalid file type. Only .py files are allowed.'
    file_path = Path(filename)
    if not file_path.is_file():
        return f"python: can't open file '{filename}': [Errno 2] No such file or directory"
    if we_are_running_in_a_docker_container():
        logger.debug(f'Auto-GPT is running in a Docker container; executing {file_path} directly...')
        result = subprocess.run(['python', str(file_path)], capture_output=True, encoding='utf8', cwd=agent.config.workspace_path)
        if result.returncode == 0:
            return result.stdout
        else:
            return f'Error: {result.stderr}'
    logger.debug('Auto-GPT is not running in a Docker container')
    try:
        client = docker.from_env()
        image_name = 'python:3-alpine'
        try:
            client.images.get(image_name)
            logger.debug(f"Image '{image_name}' found locally")
        except ImageNotFound:
            logger.info(f"Image '{image_name}' not found locally, pulling from Docker Hub...")
            low_level_client = docker.APIClient()
            for line in low_level_client.pull(image_name, stream=True, decode=True):
                status = line.get('status')
                progress = line.get('progress')
                if status and progress:
                    logger.info(f'{status}: {progress}')
                elif status:
                    logger.info(status)
        logger.debug(f'Running {file_path} in a {image_name} container...')
        container: DockerContainer = client.containers.run(image_name, ['python', file_path.relative_to(agent.workspace.root).as_posix()], volumes={str(agent.config.workspace_path): {'bind': '/workspace', 'mode': 'rw'}}, working_dir='/workspace', stderr=True, stdout=True, detach=True)
        container.wait()
        logs = container.logs().decode('utf-8')
        container.remove()
        return logs
    except DockerException as e:
        logger.warn("Could not run the script in a container. If you haven't already, please install Docker https://docs.docker.com/get-docker/")
        return f'Error: {str(e)}'
    except Exception as e:
        return f'Error: {str(e)}'

